<script setup lang="ts">
import { computed, nextTick, ref, useId } from 'vue'
const id=useId()
const expanded=ref(true)
const current=ref('overview')
const query=ref('')
const heading=ref<HTMLElement|null>(null)
const links=[{id:'overview',label:'Overview',group:'Workspace'},{id:'activity',label:'Activity',group:'Workspace'},{id:'help',label:'Help',group:'Support'}]
const visible=computed(()=>links.filter(x=>x.label.toLowerCase().includes(query.value.trim().toLowerCase())))
async function go(route:string){current.value=route;await nextTick();heading.value?.focus()}
function reset(){expanded.value=true;current.value='overview';query.value=''}
</script>
<template>
<section class="sidebar-organism-demo" aria-label="Sidebar navigation example"><div class="sidebar-organism-shell"><aside aria-label="Fictitious workspace"><strong>Sample workspace</strong><button type="button" :aria-expanded="expanded" :aria-controls="id+'-body'" @click="expanded=!expanded">{{ expanded?'Hide navigation':'Show navigation' }}</button><div v-show="expanded" :id="id+'-body'" class="sidebar-body"><label>Filter destinations<input v-model="query" type="search" maxlength="60"></label><nav aria-label="Local example destinations"><template v-for="group in ['Workspace','Support']" :key="group"><div v-if="visible.some(x=>x.group===group)" class="sidebar-section"><p>{{ group }}</p><a v-for="link in visible.filter(x=>x.group===group)" :key="link.id" :href="'#'+id+'-page-'+link.id" :aria-current="current===link.id?'page':undefined" @click.prevent="go(link.id)">{{ link.label }}</a></div></template><p v-if="!visible.length">No matching destinations. Clear the filter.</p></nav></div><footer>Example account<br><small>Fictitious identity, no account actions</small></footer></aside><div class="sidebar-organism-content"><h3 :id="id+'-page-'+current" ref="heading" tabindex="-1">{{ links.find(x=>x.id===current)?.label }}</h3><p>Local {{ current }} content. Navigation changes this panel only; no real route, account or permission changes.</p><button type="button" @click="reset">Reset example</button></div></div><p role="status">Local page: {{ current }}. {{ visible.length }} matching destinations. Navigation {{ expanded?'shown':'hidden' }}.</p></section>
</template>
<style scoped>
.sidebar-organism-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.sidebar-organism-shell{display:grid;grid-template-columns:minmax(180px,.9fr) minmax(0,1.1fr);gap:20px}.sidebar-organism-demo aside{display:flex;flex-direction:column;gap:16px;padding:14px;background:var(--vp-c-bg-soft);border-radius:10px;min-width:0}.sidebar-organism-demo button{padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.sidebar-body{animation:sidebar-body-in .16s ease-out}.sidebar-organism-demo label{display:grid;gap:6px;font-size:13px;font-weight:650}.sidebar-organism-demo input{width:100%;box-sizing:border-box;min-width:0;font:inherit;color:inherit;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg)}.sidebar-section p{font-size:12px;color:var(--vp-c-text-2);margin:16px 0 6px}.sidebar-section a{display:block;padding:8px;border-radius:8px;overflow-wrap:anywhere}.sidebar-section a[aria-current=page]{background:var(--vp-c-brand-soft);font-weight:650}.sidebar-organism-demo footer{margin-top:auto;border-top:1px solid var(--vp-c-divider);padding-top:14px;font-size:14px;overflow-wrap:anywhere}.sidebar-organism-content{min-width:0;overflow-wrap:anywhere}.sidebar-organism-content h3{scroll-margin-top:110px}.sidebar-organism-demo a:focus-visible,.sidebar-organism-demo input:focus-visible,.sidebar-organism-demo button:focus-visible,.sidebar-organism-content h3:focus{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}@keyframes sidebar-body-in{from{opacity:0;transform:translateX(-3px)}to{opacity:1;transform:none}}@media(max-width:700px){.sidebar-organism-shell{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.sidebar-body{animation:none}}
</style>
